			shadowRef:        h.shadowRef,
			headTree:         h.headTree,
			parentTree:       h.parentTree,
			repoDir:          h.repoDir,
			parentCommitHash: h.parentCommitHash(),
			headCommitHash:   h.newHead,
			allAgentFiles:    h.allAgentFiles,
