		headTree:      h.headTree,
		shadowTree:    h.shadowTree,
		parentTree:    h.parentTree,
		hasParentTree: true,
	}) {
		return true, session.AttachReasonFileOverlap
	}
	return false, session.AttachSkipContentMismatch
}

